const data = $('Source 1').first().json;

// Extract hourly records
const times = data.hourly.time;
const pm10Values = data.hourly.pm10;
const pm25Values = data.hourly.pm2_5;

// Group by date (first 10 characters of time)
const grouped = {};
for (let i = 0; i < times.length; i++) {
  const date = times[i].substring(0, 10);
  if (!grouped[date]) {
    grouped[date] = [];
  }
  grouped[date].push({
    time: times[i],
    pm10: pm10Values[i],
    pm2_5: pm25Values[i]
  });
}

// Compute daily summaries
const records = [];
for (const date in grouped) {
  const dayRecords = grouped[date];

  // Find max values for the day
  let pm10Max = -Infinity;
  let pm25Max = -Infinity;

  for (const record of dayRecords) {
    if (record.pm10 > pm10Max) pm10Max = record.pm10;
    if (record.pm2_5 > pm25Max) pm25Max = record.pm2_5;
  }

  records.push({
    date: date,
    hours: dayRecords.length,
    pm10_max: pm10Max,
    pm2_5_max: pm25Max
  });
}

return [{ json: { records } }];
